#!/usr/bin/env python3
"""Copy agave's solana-gossip out of its workspace into vendor/solana-gossip.

Usage: vendor/vendor-gossip.py <agave checkout at the tag Colibri uses> <tag>

Its `workspace = true` keys are filled in from agave's root manifest: agave's
own crates point back at the same git tag, so Cargo unifies them with the
copies the rest of Colibri already uses and only solana-gossip is replaced.
Dev-dependencies, benches and the frozen-abi / conformance features are left
out: Colibri builds none of them. Apply PATCH.md's change after running it.
"""
import shutil, sys, tomllib
from pathlib import Path

agave, tag = Path(sys.argv[1]), sys.argv[2]
out = Path(__file__).parent / "solana-gossip"
root = tomllib.loads((agave / "Cargo.toml").read_text())["workspace"]
crate = tomllib.loads((agave / "gossip/Cargo.toml").read_text())
GIT = "https://github.com/anza-xyz/agave.git"

def resolve(name, spec):
    base = root["dependencies"][name]
    base = {"version": base} if isinstance(base, str) else dict(base)
    if "path" in base:  # an agave crate: same tag, from git
        base = {"git": GIT, "tag": tag, **{k: v for k, v in base.items() if k not in ("path", "version")}}
    features = base.get("features", []) + spec.get("features", [])
    base.update({k: v for k, v in spec.items() if k not in ("workspace", "features")})
    if features:
        base["features"] = sorted(set(features))
    return base

def value(v):
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, str): return f'"{v}"'
    if isinstance(v, list): return "[" + ", ".join(value(x) for x in v) + "]"
    return "{ " + ", ".join(f"{k} = {value(x)}" for k, x in v.items()) + " }"

deps = {n: resolve(n, s) for n, s in crate["dependencies"].items() if not s.get("optional")}
features = {k: v for k, v in crate["features"].items() if k in ("agave-unstable-api", "dev-context-only-utils")}
package = {"name": "solana-gossip", **{k: root["package"][k] for k in ("version", "edition", "license", "repository")}}

lines = ["# Generated by vendor-gossip.py from agave " + tag + "; see PATCH.md.", "[package]"]
lines += [f"{k} = {value(v)}" for k, v in package.items()]
lines += ["", "[features]"] + [f'"{k}" = {value(v)}' for k, v in features.items()]
lines += ["", "[dependencies]"] + [f"{n} = {value(s)}" for n, s in sorted(deps.items())]
# The source still names the features left out above.
lines += ["", "[lints.rust]", 'unexpected_cfgs = "allow"']

shutil.rmtree(out, ignore_errors=True)
shutil.copytree(agave / "gossip/src", out / "src")
(out / "Cargo.toml").write_text("\n".join(lines) + "\n")
print(f"{out}: {len(deps)} dependencies")
